// GENERADO por scripts/build-game.mjs a partir de assets/games/ronnie-skate.src.html. No editar a mano.
export const RONNIE_SKATE_HTML: string = "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n  <title>El patinador profesional de Ronnie - Ronnie's Twilight Skate</title>\n  <script src=\"https://cdn.tailwindcss.com/3.4.17\"></script>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Press+Start+2P&family=Inter:wght@400;600;800&display=swap\" rel=\"stylesheet\">\n  <style>\n    * {\n      touch-action: manipulation;\n      user-select: none;\n      -webkit-user-select: none;\n    }\n    body {\n      background-color: #2b254a;\n      font-family: 'Press Start 2P', monospace, sans-serif;\n      overflow: hidden;\n    }\n    .pixel-art {\n      image-rendering: -moz-crisp-edges;\n      image-rendering: -webkit-crisp-edges;\n      image-rendering: pixelated;\n      image-rendering: crisp-edges;\n    }\n    .crt-overlay::after {\n      content: \" \";\n      display: block;\n      position: absolute;\n      top: 0; left: 0; bottom: 0; right: 0;\n      background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.03), rgba(0, 255, 0, 0.01), rgba(0, 0, 255, 0.03));\n      z-index: 20;\n      background-size: 100% 3px, 6px 100%;\n      pointer-events: none;\n      opacity: 0.85;\n    }\n    .vignette {\n      box-shadow: inset 0 0 80px rgba(28, 22, 54, 0.8);\n    }\n    @keyframes pulse-soft {\n      0%, 100% { transform: scale(1); opacity: 0.9; }\n      50% { transform: scale(1.05); opacity: 1; }\n    }\n    .pulse-btn {\n      animation: pulse-soft 2s infinite ease-in-out;\n    }\n  </style>\n<style>\nhtml,body{height:100%;margin:0;background:#241e3d;overflow:hidden;overscroll-behavior:none;-webkit-tap-highlight-color:transparent}\nbody{display:block !important;padding:0 !important}\n/* Marco: ocupa toda la pantalla vertical, sin bordes ni esquinas de escritorio */\n#game-wrapper{max-width:none !important;max-height:none !important;width:100% !important;height:100% !important;border:0 !important;border-radius:0 !important;box-shadow:none !important}\n/* Escenario 16:9 de ancho completo; el resto de la altura es para los botones táctiles */\n#canvas-container{flex:none !important;width:100% !important;height:auto !important;aspect-ratio:16/9}\n#gameCanvas{object-fit:contain}\n#touch-controls{flex:1 !important;min-height:0;padding:14px !important;gap:12px !important;align-items:stretch !important}\n#touch-controls button{height:100% !important;max-height:190px;min-height:92px;font-size:15px}\n#touch-controls button span:first-child{font-size:24px !important}\n#touch-controls button span:last-child{font-size:10px !important;margin-top:6px !important}\n/* HUD compacto: estrellas, vidas, puntos y botones */\nheader{padding:8px 10px !important;gap:6px}\n#btn-crt,#speed-box,#hud-title{display:none !important}\n#rec-chip{font-size:10px;white-space:nowrap}\nheader button{min-width:40px;min-height:40px}\n/* Menús (inicio, pausa, game over) cubren TODA la pantalla, no solo el escenario */\n#start-screen,#game-over-screen,#pause-screen{position:fixed !important;inset:0 !important;overflow-y:auto;justify-content:flex-start !important;padding:24px 18px !important}\n#start-screen h1{font-size:20px !important;line-height:1.6 !important}\n#start-screen p{font-size:10px !important;line-height:1.8 !important}\n#start-screen .text-[9px],#start-screen .text-[10px],#start-screen .text-xs{font-size:10px !important;line-height:1.7 !important}\n#btn-play,#btn-restart,#btn-resume{min-height:56px;font-size:13px !important}\n#start-screen *,#game-over-screen *,#pause-screen *{overflow-wrap:anywhere}\n</style>\n</head>\n<body class=\"w-screen h-screen flex flex-col items-center justify-center p-0 m-0 bg-[#241e3d] text-slate-100\">\n\n  <!-- Main Game Container -->\n  <div id=\"game-wrapper\" class=\"relative w-full h-full max-w-[1050px] max-h-[640px] flex flex-col bg-[#302b54] shadow-2xl rounded-none md:rounded-2xl overflow-hidden border-0 md:border-4 border-[#615c8e]\">\n    \n    <!-- Top Bar / Header HUD -->\n    <header class=\"w-full bg-[#1e1933] border-b-2 border-[#4c4573] px-3 py-2 flex items-center justify-between text-[10px] md:text-xs z-30 select-none\">\n      <div class=\"flex items-center gap-2 md:gap-4\">\n        <span id=\"hud-title\" class=\"text-[#a4aeff] font-bold tracking-wider\">RONNIE SKATE</span>\n        <div class=\"flex items-center gap-1 text-[#f39c12] bg-[#2d264f] px-2 py-1 rounded border border-[#524982]\">\n          <span>★</span>\n          <span id=\"stars-display\">0</span>\n        </div>\n        <div class=\"hidden sm:flex items-center gap-1 text-[#48dbfb] bg-[#2d264f] px-2 py-1 rounded border border-[#524982]\">\n          <span>DIST:</span>\n          <span id=\"distance-display\">0m</span>\n        </div>\n      </div>\n\n      <!-- Center Ghost Lives -->\n      <div class=\"flex items-center gap-1\">\n        <span class=\"text-[9px] text-[#b0a8d6] mr-1 hidden xs:inline\">VIDAS:</span>\n        <div id=\"hearts-container\" class=\"flex gap-1\">\n          <span class=\"text-base text-[#ff6b81] filter drop-shadow\">👻</span>\n          <span class=\"text-base text-[#ff6b81] filter drop-shadow\">👻</span>\n          <span class=\"text-base text-[#ff6b81] filter drop-shadow\">👻</span>\n        </div>\n      </div>\n\n      <!-- Right Controls & Score -->\n      <div class=\"flex items-center gap-2\">\n        <div class=\"bg-[#2d264f] px-2 py-1 rounded border border-[#524982] text-[#ffdd59]\">\n          <span class=\"text-[9px] text-[#b0a8d6] mr-1 hidden sm:inline\">PTS:</span>\n          <span id=\"score-display\">00000</span>\n        </div>\n        \n        <div id=\"rec-chip\" class=\"bg-[#2d264f] px-2 py-1 rounded border border-[#524982] text-[#1dd1a1]\"><span class=\"text-[9px] text-[#b0a8d6] mr-1\">REC:</span><span id=\"rec-display\">0</span></div>\n        <!-- Action Buttons -->\n        <button id=\"btn-sound\" class=\"p-1.5 bg-[#3a3263] hover:bg-[#4d4380] border border-[#61579a] rounded text-xs transition\" title=\"Activar/Silenciar sonido\" aria-label=\"Sonido\">\n          <span id=\"sound-icon\">🔇</span>\n        </button>\n        <button id=\"btn-crt\" class=\"p-1.5 bg-[#3a3263] hover:bg-[#4d4380] border border-[#61579a] rounded text-[9px] text-[#b9b2e8] transition\" title=\"Filtro Retro CRT\">\n          CRT\n        </button>\n        <button id=\"btn-pause\" class=\"p-1.5 bg-[#3a3263] hover:bg-[#4d4380] border border-[#61579a] rounded text-xs transition\" title=\"Pausar juego\" aria-label=\"Pausa\">\n          ⏸\n        </button>\n      </div>\n    </header>\n\n    <!-- Canvas Frame -->\n    <div id=\"canvas-container\" class=\"relative flex-1 w-full h-full bg-[#1b1730] overflow-hidden vignette\">\n      <canvas id=\"gameCanvas\" class=\"pixel-art absolute top-0 left-0 w-full h-full\"></canvas>\n\n      <!-- Dynamic Trick / Combo Banner Overlay -->\n      <div id=\"record-banner\" class=\"absolute top-2 left-1/2 -translate-x-1/2 pointer-events-none z-30 opacity-0 transition-opacity duration-300 text-center\"><div class=\"px-3 py-2 rounded-xl border-2 border-[#feca57] bg-[#1e1933]/95 text-[#feca57] text-xs font-bold\">🏆 ¡NUEVO RÉCORD!</div></div>\n      <div id=\"trick-banner\" class=\"absolute top-6 left-1/2 -translate-x-1/2 pointer-events-none opacity-0 transition-all duration-300 transform -translate-y-2 flex flex-col items-center z-20\">\n        <div id=\"trick-name\" class=\"text-sm md:text-base font-bold text-[#feca57] tracking-wider drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)]\">\n          KICKFLIP!\n        </div>\n        <div id=\"trick-points\" class=\"text-[10px] md:text-xs text-[#54a0ff] mt-0.5 font-bold\">\n          +150 PTS\n        </div>\n      </div>\n\n      <!-- Combo Multiplier Badge -->\n      <div id=\"combo-badge\" class=\"absolute top-4 left-4 bg-[#ff6b81] text-white text-[10px] md:text-xs px-2.5 py-1 rounded-full font-bold border-2 border-white shadow-lg opacity-0 transition-opacity duration-200 pointer-events-none z-20\">\n        x2 COMBO!\n      </div>\n\n      <!-- Speed & Boost Bar -->\n      <div id=\"speed-box\" class=\"absolute bottom-3 left-3 bg-[#1e1933]/90 backdrop-blur px-2 py-1 rounded border border-[#524982] text-[9px] flex items-center gap-2 pointer-events-none z-20\">\n        <span class=\"text-[#a4aeff]\">VELOCIDAD:</span>\n        <div class=\"w-16 h-2 bg-[#120f21] rounded-full overflow-hidden border border-[#443a6d]\">\n          <div id=\"speed-meter\" class=\"h-full bg-gradient-to-r from-[#54a0ff] via-[#5f27cd] to-[#ff6b81] transition-all duration-300\" style=\"width: 25%\"></div>\n        </div>\n        <span id=\"speed-text\" class=\"text-[#feca57]\">24 km/h</span>\n      </div>\n\n      <!-- Start / Menu Screen Overlay -->\n      <div id=\"start-screen\" class=\"absolute inset-0 bg-[#201b38]/90 backdrop-blur-sm flex flex-col items-center justify-center p-4 z-40\">\n        <div class=\"max-w-md w-full text-center flex flex-col items-center\">\n          <div class=\"inline-block px-3 py-1 bg-[#473e75] text-[#b9b2e8] text-[9px] rounded-full mb-3 tracking-widest border border-[#6b5ea8]\">\n            PIXEL ART RETRO SKATER\n          </div>\n          <h1 class=\"text-xl md:text-2xl text-[#f5f6fa] font-extrabold tracking-wide mb-2 drop-shadow-md leading-relaxed\">\n            EL PATINADOR<br><span class=\"text-[#a29bfe]\">PROFESIONAL</span><br>DE RONNIE\n          </h1>\n          <p class=\"text-[10px] text-[#d6d1f5] mb-6 leading-relaxed max-w-sm\">\n            ¡Patina por la ciudad crepuscular, esquiva rocas, salta sobre barandillas y recoge estrellas con el fantasma Ronnie!\n          </p>\n\n          <!-- Instructions Card -->\n          <div class=\"w-full bg-[#2d254f] border border-[#584c8a] rounded-xl p-3 mb-6 text-[9px] text-[#cfc8f2] text-left space-y-2\">\n            <div class=\"flex items-center justify-between border-b border-[#3f356d] pb-1.5\">\n              <span class=\"text-[#feca57]\">BOTÓN SALTO (o ESPACIO):</span>\n              <span class=\"text-white font-bold\">Ollie (Salto / Doble)</span>\n            </div>\n            <div class=\"flex items-center justify-between border-b border-[#3f356d] pb-1.5\">\n              <span class=\"text-[#54a0ff]\">BOTÓN TRUCO (o X):</span>\n              <span class=\"text-white font-bold\">Truco aéreo (Kickflip)</span>\n            </div>\n            <div class=\"flex items-center justify-between border-b border-[#3f356d] pb-1.5\">\n              <span class=\"text-[#ff9ff3]\">BOTÓN DESLIZAR (o S):</span>\n              <span class=\"text-white font-bold\">Deslizarse (Agacharse)</span>\n            </div>\n            <div class=\"flex items-center justify-between pt-0.5\">\n              <span class=\"text-[#1dd1a1]\">BARANDILLAS:</span>\n              <span class=\"text-white font-bold\">¡Grinda para combo!</span>\n            </div>\n          </div>\n\n          <div id=\"start-record\" class=\"w-full mb-3 py-2.5 rounded-xl border-2 border-[#feca57]/60 bg-[#2d264f] text-center text-[10px] text-[#feca57] font-bold\"></div>\n          <button id=\"btn-play\" class=\"pulse-btn w-full py-3.5 bg-gradient-to-r from-[#6c5ce7] to-[#a29bfe] hover:from-[#5b4cc4] hover:to-[#8e85ee] text-white text-xs md:text-sm font-bold rounded-xl border-2 border-[#d6d1f5] shadow-[0_4px_15px_rgba(108,92,231,0.5)] transition active:scale-95\">\n            ¡A PATINAR! (START)\n          </button>\n        </div>\n      </div>\n\n      <!-- Game Over Overlay -->\n      <div id=\"game-over-screen\" class=\"hidden absolute inset-0 bg-[#1a152e]/95 backdrop-blur-md flex flex-col items-center justify-center p-4 z-40\">\n        <div class=\"max-w-md w-full text-center flex flex-col items-center\">\n          <div class=\"text-3xl mb-2\">💥</div>\n          <h2 class=\"text-xl md:text-2xl text-[#ff6b81] font-bold mb-4 drop-shadow\">\n            ¡FIN DEL VIAJE!\n          </h2>\n\n          <div class=\"w-full bg-[#2a224a] border border-[#594d87] rounded-xl p-4 mb-5 text-[10px] space-y-2.5\">\n            <div class=\"flex justify-between items-center text-[#dcd6f7]\">\n              <span>PUNTUACIÓN:</span>\n              <span id=\"final-score\" class=\"text-base text-[#feca57] font-bold\">0</span>\n            </div>\n            <div class=\"flex justify-between items-center text-[#dcd6f7]\">\n              <span id=\"new-record-badge\" class=\"hidden text-[#feca57] font-bold\">🏆 ¡NUEVO RÉCORD!</span><span>MEJOR RÉCORD:</span>\n              <span id=\"high-score\" class=\"text-sm text-[#1dd1a1] font-bold\">0</span>\n            </div>\n            <div class=\"flex justify-between items-center text-[#dcd6f7]\">\n              <span>DISTANCIA RECORRIDA:</span>\n              <span id=\"final-dist\" class=\"text-[#54a0ff]\">0m</span>\n            </div>\n            <div class=\"flex justify-between items-center text-[#dcd6f7]\">\n              <span>ESTRELLAS RECOGIDAS:</span>\n              <span id=\"final-stars\" class=\"text-[#ff9ff3]\">0</span>\n            </div>\n            <div class=\"flex justify-between items-center text-[#dcd6f7]\">\n              <span>TRUCOS EJECUTADOS:</span>\n              <span id=\"final-tricks\" class=\"text-[#feca57]\">0</span>\n            </div>\n          </div>\n\n          <button id=\"btn-restart\" class=\"w-full py-3.5 bg-gradient-to-r from-[#ff6b81] to-[#ff4757] hover:from-[#ee5253] hover:to-[#eb3b5a] text-white text-xs md:text-sm font-bold rounded-xl border-2 border-[#ffc2c9] shadow-[0_4px_15px_rgba(255,107,129,0.4)] transition active:scale-95\">\n            REINTENTAR (ESPACIO)\n          </button>\n        </div>\n      </div>\n\n      <!-- Pause Overlay -->\n      <div id=\"pause-screen\" class=\"hidden absolute inset-0 bg-[#161226]/80 backdrop-blur-sm flex flex-col items-center justify-center p-4 z-40\">\n        <h2 class=\"text-xl text-[#feca57] font-bold mb-4\">PAUSA</h2>\n        <button id=\"btn-resume\" class=\"px-6 py-3 bg-[#6c5ce7] hover:bg-[#5848c2] text-white text-xs font-bold rounded-xl border border-[#a29bfe] transition\">\n          CONTINUAR\n        </button>\n      </div>\n\n    </div>\n\n    <!-- Bottom Touch Controls (Mobile Friendly & On-Screen) -->\n    <div id=\"touch-controls\" class=\"w-full bg-[#1e1933] border-t-2 border-[#4c4573] p-2.5 flex items-center justify-around gap-2 select-none z-30\">\n      <button id=\"touch-slide\" class=\"flex-1 py-3 bg-[#3a3263] active:bg-[#52468c] border-2 border-[#5d5294] rounded-xl text-center flex flex-col items-center justify-center transition active:scale-95\">\n        <span class=\"text-sm\">🛹 ⬇</span>\n        <span class=\"text-[9px] text-[#dcd6f7] font-bold mt-0.5\">DESLIZAR</span>\n      </button>\n\n      <button id=\"touch-trick\" class=\"flex-1 py-3 bg-[#4d3877] active:bg-[#684c9f] border-2 border-[#7657b5] rounded-xl text-center flex flex-col items-center justify-center transition active:scale-95\">\n        <span class=\"text-sm\">✨ ⤾</span>\n        <span class=\"text-[9px] text-[#feca57] font-bold mt-0.5\">TRUCO</span>\n      </button>\n\n      <button id=\"touch-jump\" class=\"flex-1 py-3 bg-[#384877] active:bg-[#4960a1] border-2 border-[#5470b9] rounded-xl text-center flex flex-col items-center justify-center transition active:scale-95\">\n        <span class=\"text-sm\">🚀 ⬆</span>\n        <span class=\"text-[9px] text-[#48dbfb] font-bold mt-0.5\">OLLIE / SALTO</span>\n      </button>\n    </div>\n\n  </div>\n\n  <script>\n    // --- AUDIO SYSTEM (Web Audio API Synthesizer) ---\n    class SoundEngine {\n      constructor() {\n        this.ctx = null;\n        this.muted = true;\n        this.initialized = false;\n        this.bgmTimer = null;\n        this.step = 0;\n      }\n\n      init() {\n        if (this.initialized) return;\n        try {\n          const AudioContext = window.AudioContext || window.webkitAudioContext;\n          if (AudioContext) {\n            this.ctx = new AudioContext();\n            this.initialized = true;\n          }\n        } catch (e) {\n          console.warn('Audio not available', e);\n        }\n      }\n\n      resume() {\n        if (this.ctx && this.ctx.state === 'suspended') {\n          this.ctx.resume();\n        }\n      }\n\n      toggleMute() {\n        this.muted = !this.muted;\n        return this.muted;\n      }\n\n      playTone(freq, duration, type = 'sine', gainVal = 0.1, freqEnd = null) {\n        if (!this.initialized || this.muted || !this.ctx) return;\n        this.resume();\n        const t = this.ctx.currentTime;\n        const osc = this.ctx.createOscillator();\n        const gain = this.ctx.createGain();\n\n        osc.type = type;\n        osc.frequency.setValueAtTime(freq, t);\n        if (freqEnd !== null) {\n          osc.frequency.exponentialRampToValueAtTime(Math.max(10, freqEnd), t + duration);\n        }\n\n        gain.gain.setValueAtTime(gainVal, t);\n        gain.gain.exponentialRampToValueAtTime(0.0001, t + duration);\n\n        osc.connect(gain);\n        gain.connect(this.ctx.destination);\n\n        osc.start(t);\n        osc.stop(t + duration);\n      }\n\n      jump() {\n        this.playTone(160, 0.18, 'triangle', 0.15, 480);\n      }\n\n      trick() {\n        this.playTone(400, 0.08, 'square', 0.08, 700);\n        setTimeout(() => this.playTone(600, 0.12, 'square', 0.1, 950), 60);\n      }\n\n      star() {\n        this.playTone(587.33, 0.12, 'sine', 0.12); // D5\n        setTimeout(() => this.playTone(880, 0.22, 'sine', 0.14), 70); // A5\n      }\n\n      grind() {\n        if (!this.initialized || this.muted || !this.ctx) return;\n        if (Math.random() < 0.4) {\n          this.playTone(120 + Math.random() * 80, 0.04, 'sawtooth', 0.04);\n        }\n      }\n\n      hit() {\n        this.playTone(180, 0.28, 'sawtooth', 0.2, 45);\n      }\n\n      gameOver() {\n        const notes = [392, 349.23, 311.13, 261.63];\n        notes.forEach((freq, idx) => {\n          setTimeout(() => this.playTone(freq, 0.28, 'triangle', 0.15), idx * 160);\n        });\n      }\n\n      startBGM() {\n        if (!this.initialized || this.bgmTimer) return;\n        // Lo-fi twilight chord progression: Cmaj7, Am7, Fmaj7, G6\n        const chords = [\n          [261.63, 329.63, 392.00, 493.88], // Cmaj7\n          [220.00, 261.63, 329.63, 392.00], // Am7\n          [174.61, 220.00, 261.63, 329.63], // Fmaj7\n          [196.00, 246.94, 293.66, 392.00]  // G6\n        ];\n        const bass = [130.81, 110.00, 87.31, 98.00];\n\n        let tick = 0;\n        this.bgmTimer = setInterval(() => {\n          if (this.muted || !this.ctx || this.ctx.state !== 'running') return;\n          const chordIdx = Math.floor(tick / 8) % chords.length;\n          const stepInChord = tick % 8;\n\n          // Bass note on beat 0 and 4\n          if (stepInChord === 0 || stepInChord === 4) {\n            this.playTone(bass[chordIdx], 0.35, 'triangle', 0.07);\n          }\n\n          // Arpeggiated soft chime\n          const currentChord = chords[chordIdx];\n          const noteFreq = currentChord[stepInChord % currentChord.length];\n          this.playTone(noteFreq * 2, 0.18, 'sine', 0.035);\n\n          tick++;\n        }, 220);\n      }\n\n      stopBGM() {\n        if (this.bgmTimer) {\n          clearInterval(this.bgmTimer);\n          this.bgmTimer = null;\n        }\n      }\n    }\n\n    const sound = new SoundEngine();\n\n    // --- GAME ENGINE & STATE ---\n    const canvas = document.getElementById('gameCanvas');\n    const ctx = canvas.getContext('2d');\n    const container = document.getElementById('canvas-container');\n\n    // UI Elements\n    const starsDisplay = document.getElementById('stars-display');\n    const distanceDisplay = document.getElementById('distance-display');\n    const scoreDisplay = document.getElementById('score-display');\n    const speedMeter = document.getElementById('speed-meter');\n    const speedText = document.getElementById('speed-text');\n    const heartsContainer = document.getElementById('hearts-container');\n    const trickBanner = document.getElementById('trick-banner');\n    const trickNameEl = document.getElementById('trick-name');\n    const trickPointsEl = document.getElementById('trick-points');\n    const comboBadge = document.getElementById('combo-badge');\n    const startScreen = document.getElementById('start-screen');\n    const gameOverScreen = document.getElementById('game-over-screen');\n    const pauseScreen = document.getElementById('pause-screen');\n    const finalScoreEl = document.getElementById('final-score');\n    const highScoreEl = document.getElementById('high-score');\n    const finalDistEl = document.getElementById('final-dist');\n    const finalStarsEl = document.getElementById('final-stars');\n    const finalTricksEl = document.getElementById('final-tricks');\n    const soundIcon = document.getElementById('sound-icon');\n\n    // Game Constants\n    const VIRTUAL_WIDTH = 480;\n    const VIRTUAL_HEIGHT = 270;\n    const GROUND_Y = 222;\n\n    // Palette extracted from user reference image\n    const PALETTE = {\n      skyTop: '#5f6cb8',\n      skyMid: '#7887e2',\n      skyBottom: '#9ea9eb',\n      moon: '#f7f1cb',\n      moonGlow: 'rgba(247, 241, 203, 0.25)',\n      clouds: '#c2c9f5',\n      mountains: '#686a9f',\n      skylineFar: '#505080',\n      skylineNear: '#3b3863',\n      windowYellow: '#ffea79',\n      windowCyan: '#7ee8fa',\n      water: '#444170',\n      waterHighlight: '#6e77bf',\n      railing: '#2e2b52',\n      railingPost: '#3d3968',\n      bushGreen: '#5b6999',\n      bushHighlight: '#8091cc',\n      sidewalkTop: '#8c84aa',\n      sidewalkFace: '#4c4978',\n      sidewalkLine: '#332f57',\n      stoneRock: '#7b7696',\n      stoneShadow: '#443f60',\n      stoneHighlight: '#a39ebc',\n      ghostWhite: '#ffffff',\n      ghostShade: '#dcd7f5',\n      ghostCap: '#58498f',\n      ghostCapVisor: '#3a2d6b',\n      skateboardDeck: '#7f8c8d',\n      skateboardWheel: '#2ecc71',\n      starYellow: '#f1c40f',\n      spark: '#ffea79'\n    };\n\n    // Game Variables\n    let gameState = 'START'; // 'START', 'PLAYING', 'PAUSED', 'GAMEOVER'\n    let score = 0;\n    let highScore = 0;\n    try {\n      highScore = parseInt(localStorage.getItem('ronnie_high_score') || '0', 10);\n    } catch(e) {}\n    if (window.__VITRA_RECORD && window.__VITRA_RECORD > highScore) highScore = Math.floor(window.__VITRA_RECORD);\n    let recordBroken = false;\n    let recordToBeat = highScore; // el récord con el que empieza la partida\n    function vitraSend(msg) { if (window.ReactNativeWebView) window.ReactNativeWebView.postMessage(JSON.stringify(msg)); }\n    let distance = 0;\n    let starsCollected = 0;\n    let tricksCount = 0;\n    let lives = 3;\n    let gameSpeed = 3.6;\n    let baseSpeed = 3.6;\n    let maxSpeed = 7.5;\n    let combo = 1;\n    let comboTimer = 0;\n    let trickTimeout = null;\n\n    // Parallax Offsets\n    let bgOffsetClouds = 0;\n    let bgOffsetMountains = 0;\n    let bgOffsetSkylineFar = 0;\n    let bgOffsetSkylineNear = 0;\n    let bgOffsetWater = 0;\n    let bgOffsetRailing = 0;\n    let bgOffsetGround = 0;\n\n    // Entities Arrays\n    let obstacles = [];\n    let collectibles = [];\n    let particles = [];\n    let floatTexts = [];\n    let railingSegments = [];\n\n    // Player Object: Ronnie the Ghost\n    const player = {\n      x: 75,\n      y: GROUND_Y - 32,\n      baseY: GROUND_Y - 32,\n      w: 32,\n      h: 34,\n      vy: 0,\n      gravity: 0.65,\n      jumpForce: -9.8,\n      isGrounded: true,\n      canDoubleJump: true,\n      isSliding: false,\n      slideTimer: 0,\n      isGrinding: false,\n      isDoingTrick: false,\n      trickAngle: 0,\n      trickName: '',\n      invulnerableTimer: 0,\n      floatFrame: 0,\n      tailFrame: 0,\n      boardTilt: 0,\n\n      reset() {\n        this.y = this.baseY;\n        this.vy = 0;\n        this.isGrounded = true;\n        this.canDoubleJump = true;\n        this.isSliding = false;\n        this.slideTimer = 0;\n        this.isGrinding = false;\n        this.isDoingTrick = false;\n        this.trickAngle = 0;\n        this.invulnerableTimer = 0;\n        this.boardTilt = 0;\n      },\n\n      jump() {\n        if (this.isGrounded || this.isGrinding) {\n          this.vy = this.jumpForce;\n          this.isGrounded = false;\n          this.isGrinding = false;\n          this.canDoubleJump = true;\n          this.isSliding = false;\n          this.boardTilt = -0.3;\n          createDust(this.x + 12, GROUND_Y, 6);\n          sound.jump();\n        } else if (this.canDoubleJump) {\n          this.vy = this.jumpForce * 0.9;\n          this.canDoubleJump = false;\n          this.doTrick('DOUBLE OLLIE', 100);\n          sound.jump();\n          createSparks(this.x + 16, this.y + 20, 8, PALETTE.ghostShade);\n        }\n      },\n\n      slide() {\n        if (this.isGrounded && !this.isSliding) {\n          this.isSliding = true;\n          this.slideTimer = 35; // Frames of slide\n          createDust(this.x + 8, GROUND_Y, 3);\n          sound.playTone(280, 0.1, 'sine', 0.05, 180);\n        }\n      },\n\n      doTrick(customName = null, bonus = 150) {\n        if (!this.isGrounded && !this.isDoingTrick) {\n          const trickList = ['KICKFLIP!', '360 SHUVIT!', 'GHOST FLIP!', 'IMPOSSIBLE!'];\n          const chosen = customName || trickList[Math.floor(Math.random() * trickList.length)];\n          this.isDoingTrick = true;\n          this.trickName = chosen;\n          this.trickAngle = 0;\n          tricksCount++;\n          addScore(bonus * combo);\n          showTrickBanner(chosen, bonus * combo);\n          sound.trick();\n          createSparks(this.x + 16, this.y + 16, 7, PALETTE.spark);\n        }\n      },\n\n      update() {\n        this.floatFrame += 0.1;\n        this.tailFrame += 0.15;\n\n        if (this.invulnerableTimer > 0) {\n          this.invulnerableTimer--;\n        }\n\n        // Slide timer\n        if (this.isSliding) {\n          this.slideTimer--;\n          if (this.slideTimer <= 0) {\n            this.isSliding = false;\n          }\n        }\n\n        // Trick animation rotation\n        if (this.isDoingTrick) {\n          this.trickAngle += 0.45;\n          if (this.trickAngle >= Math.PI * 2) {\n            this.isDoingTrick = false;\n            this.trickAngle = 0;\n          }\n        }\n\n        // Physics\n        if (!this.isGrinding) {\n          this.vy += this.gravity;\n          this.y += this.vy;\n\n          // Tilting board according to jump velocity\n          if (!this.isGrounded) {\n            this.boardTilt = Math.max(-0.4, Math.min(0.4, this.vy * 0.04));\n          } else {\n            this.boardTilt = 0;\n          }\n\n          // Ground check\n          if (this.y >= this.baseY) {\n            this.y = this.baseY;\n            this.vy = 0;\n            if (!this.isGrounded) {\n              createDust(this.x + 12, GROUND_Y, 4);\n            }\n            this.isGrounded = true;\n            this.canDoubleJump = true;\n          }\n        } else {\n          // While grinding on railing\n          this.y = GROUND_Y - 48; // Railing height\n          this.vy = 0;\n          this.isGrounded = false;\n          this.canDoubleJump = true;\n          sound.grind();\n          if (Math.random() < 0.6) {\n            createSparks(this.x + 16, GROUND_Y - 40, 2, '#fff');\n          }\n          addScore(1);\n        }\n      },\n\n      draw(c) {\n        // Flash if invulnerable\n        if (this.invulnerableTimer > 0 && Math.floor(this.invulnerableTimer / 4) % 2 === 1) {\n          return;\n        }\n\n        c.save();\n        const drawX = Math.round(this.x);\n        let drawY = Math.round(this.y);\n\n        // Skateboard Shadow\n        c.fillStyle = 'rgba(30, 24, 54, 0.45)';\n        c.beginPath();\n        const shadowScale = Math.max(0.3, 1 - (this.baseY - this.y) / 120);\n        c.ellipse(drawX + 16, GROUND_Y + 1, 14 * shadowScale, 3 * shadowScale, 0, 0, Math.PI * 2);\n        c.fill();\n\n        // Slide posture or Jump rotation\n        if (this.isSliding) {\n          // Low sleek ghost pancake on board\n          // Draw Skateboard\n          drawSkateboard(c, drawX, drawY + 16, 0);\n\n          // Flattened Ronnie\n          c.fillStyle = PALETTE.ghostWhite;\n          c.beginPath();\n          c.ellipse(drawX + 16, drawY + 18, 16, 8, 0, 0, Math.PI * 2);\n          c.fill();\n\n          // Cap backwards\n          c.fillStyle = PALETTE.ghostCap;\n          c.fillRect(drawX + 2, drawY + 13, 12, 6);\n          c.fillStyle = PALETTE.ghostCapVisor;\n          c.fillRect(drawX - 2, drawY + 15, 5, 3);\n\n          // Eyes\n          c.fillStyle = '#222';\n          c.fillRect(drawX + 22, drawY + 16, 2, 3);\n\n          // Blush\n          c.fillStyle = '#ff9ff3';\n          c.fillRect(drawX + 20, drawY + 20, 3, 2);\n\n          // Ecto trail puff\n          if (Math.random() < 0.4) {\n            createSparks(drawX, drawY + 18, 1, PALETTE.ghostShade);\n          }\n        } else {\n          // Normal or Jumping/Tricking Ghost\n          c.translate(drawX + 16, drawY + 16);\n          if (this.isDoingTrick) {\n            c.rotate(this.trickAngle);\n          } else {\n            c.rotate(this.boardTilt);\n          }\n\n          // Draw Skateboard attached to feet\n          drawSkateboard(c, -16, 10, 0);\n\n          // Ghost body float offset\n          const floatOffset = this.isGrounded ? Math.sin(this.floatFrame) * 1.5 : 0;\n\n          // Ghost Main Body (Hand-crafted pixel silhouette)\n          c.fillStyle = PALETTE.ghostWhite;\n\n          // Rounded head\n          c.beginPath();\n          c.arc(0, -6 + floatOffset, 11, Math.PI, 0, false);\n          c.lineTo(11, 8 + floatOffset);\n\n          // Wavy bottom tails\n          const wave = Math.sin(this.tailFrame) * 2;\n          c.quadraticCurveTo(6, 12 + wave + floatOffset, 0, 8 + floatOffset);\n          c.quadraticCurveTo(-6, 4 - wave + floatOffset, -11, 8 + floatOffset);\n          c.closePath();\n          c.fill();\n\n          // Soft shading on left edge\n          c.fillStyle = PALETTE.ghostShade;\n          c.fillRect(-10, -2 + floatOffset, 3, 8);\n\n          // Ronnie's Purple Skater Cap (Turned Backwards)\n          c.fillStyle = PALETTE.ghostCap;\n          c.beginPath();\n          c.arc(0, -11 + floatOffset, 10, Math.PI * 1.1, Math.PI * 1.9, false);\n          c.fill();\n          c.fillRect(-8, -14 + floatOffset, 16, 5);\n\n          // Cap Visor poking out backwards (to the left)\n          c.fillStyle = PALETTE.ghostCapVisor;\n          c.fillRect(-13, -11 + floatOffset, 6, 3);\n\n          // Cute Ghost Eyes\n          c.fillStyle = '#1c1735';\n          c.fillRect(2, -5 + floatOffset, 3, 5);\n          c.fillRect(7, -5 + floatOffset, 3, 5);\n\n          // Eye highlights\n          c.fillStyle = '#fff';\n          c.fillRect(2, -5 + floatOffset, 1, 2);\n          c.fillRect(7, -5 + floatOffset, 1, 2);\n\n          // Rosy Cheeks\n          c.fillStyle = 'rgba(255, 107, 129, 0.6)';\n          c.fillRect(0, 1 + floatOffset, 3, 2);\n          c.fillRect(9, 1 + floatOffset, 3, 2);\n        }\n\n        c.restore();\n      }\n    };\n\n    function drawSkateboard(c, x, y, angle = 0) {\n      c.save();\n      c.translate(x + 16, y + 2);\n      c.rotate(angle);\n\n      // Deck top (grip tape)\n      c.fillStyle = '#2f3542';\n      c.fillRect(-15, -2, 30, 3);\n\n      // Kicktail bevels\n      c.fillStyle = '#57606f';\n      c.fillRect(-16, -3, 3, 2);\n      c.fillRect(13, -3, 3, 2);\n\n      // Trucks\n      c.fillStyle = '#747d8c';\n      c.fillRect(-10, 1, 4, 2);\n      c.fillRect(6, 1, 4, 2);\n\n      // Neon Lime Wheels (Spinning!)\n      c.fillStyle = PALETTE.skateboardWheel;\n      c.fillRect(-12, 3, 5, 4);\n      c.fillRect(7, 3, 5, 4);\n\n      // Wheel hubs\n      c.fillStyle = '#1e272e';\n      c.fillRect(-10, 4, 2, 2);\n      c.fillRect(9, 4, 2, 2);\n\n      c.restore();\n    }\n\n    // --- OBSTACLE & ENTITY GENERATION ---\n    class Obstacle {\n      constructor(x, type) {\n        this.x = x;\n        this.type = type; // 'STONE', 'HYDRANT', 'BAT', 'BENCH'\n        this.passed = false;\n\n        if (type === 'STONE') {\n          this.w = 28;\n          this.h = 24;\n          this.y = GROUND_Y - this.h;\n        } else if (type === 'HYDRANT') {\n          this.w = 18;\n          this.h = 28;\n          this.y = GROUND_Y - this.h;\n        } else if (type === 'BAT') {\n          this.w = 24;\n          this.h = 16;\n          this.y = GROUND_Y - 54; // Head height: duck to slide under or jump very high!\n          this.frame = 0;\n        } else if (type === 'BENCH') {\n          this.w = 46;\n          this.h = 22;\n          this.y = GROUND_Y - this.h;\n          this.canGrind = true;\n        }\n      }\n\n      update() {\n        this.x -= gameSpeed;\n        if (this.type === 'BAT') {\n          this.frame += 0.2;\n          this.y += Math.sin(this.frame) * 0.6;\n        }\n      }\n\n      draw(c) {\n        const drawX = Math.round(this.x);\n        const drawY = Math.round(this.y);\n\n        if (this.type === 'STONE') {\n          // Hand-crafted pixel rock obstacle (as shown in reference screenshot)\n          c.fillStyle = PALETTE.stoneRock;\n          c.fillRect(drawX + 3, drawY + 3, this.w - 6, this.h - 3);\n\n          // Angular pixel rock edges\n          c.fillRect(drawX + 1, drawY + 8, this.w - 2, this.h - 8);\n          c.fillRect(drawX + 6, drawY, this.w - 12, 4);\n\n          // Highlights\n          c.fillStyle = PALETTE.stoneHighlight;\n          c.fillRect(drawX + 6, drawY, this.w - 12, 2);\n          c.fillRect(drawX + 2, drawY + 7, 3, 4);\n          c.fillRect(drawX + 10, drawY + 8, 4, 2);\n\n          // Shadows and cracks\n          c.fillStyle = PALETTE.stoneShadow;\n          c.fillRect(drawX + 1, drawY + this.h - 4, this.w - 2, 4);\n          c.fillRect(drawX + 12, drawY + 6, 2, 8);\n          c.fillRect(drawX + 14, drawY + 12, 4, 2);\n          c.fillRect(drawX + 20, drawY + 9, 2, 7);\n\n        } else if (this.type === 'HYDRANT') {\n          // Vintage City Fire Hydrant\n          c.fillStyle = '#e84118';\n          c.fillRect(drawX + 3, drawY + 6, 12, 20);\n          c.fillRect(drawX + 1, drawY + 22, 16, 6); // Base\n\n          // Cap & nozzles\n          c.fillStyle = '#fbc531';\n          c.fillRect(drawX + 5, drawY + 1, 8, 5); // Top bolt\n          c.fillRect(drawX, drawY + 12, 3, 5); // Left nozzle\n          c.fillRect(drawX + 15, drawY + 12, 3, 5); // Right nozzle\n\n          // Outline / shade\n          c.fillStyle = '#711e1e';\n          c.fillRect(drawX + 12, drawY + 6, 3, 20);\n\n        } else if (this.type === 'BAT') {\n          // Twilight bat\n          c.fillStyle = '#2d203e';\n          const wingY = Math.sin(this.frame) > 0 ? -4 : 4;\n\n          // Bat body\n          c.fillRect(drawX + 9, drawY + 5, 6, 7);\n          // Bat ears\n          c.fillRect(drawX + 9, drawY + 3, 2, 3);\n          c.fillRect(drawX + 13, drawY + 3, 2, 3);\n          // Red glowing eyes\n          c.fillStyle = '#ff4757';\n          c.fillRect(drawX + 10, drawY + 6, 1, 2);\n          c.fillRect(drawX + 13, drawY + 6, 1, 2);\n\n          // Wings\n          c.fillStyle = '#3f2d59';\n          c.fillRect(drawX + 2, drawY + 6 + wingY, 7, 3);\n          c.fillRect(drawX + 15, drawY + 6 + wingY, 7, 3);\n\n        } else if (this.type === 'BENCH') {\n          // Park Bench (Grindable!)\n          // Legs\n          c.fillStyle = '#2f3542';\n          c.fillRect(drawX + 4, drawY + 8, 4, 14);\n          c.fillRect(drawX + this.w - 8, drawY + 8, 4, 14);\n\n          // Wooden slats\n          c.fillStyle = '#d35400';\n          c.fillRect(drawX, drawY + 4, this.w, 5);\n          c.fillStyle = '#e67e22';\n          c.fillRect(drawX, drawY + 2, this.w, 2); // Top grind rail\n\n          // Grind indicator sparkles\n          if (Math.random() < 0.2) {\n            c.fillStyle = '#feca57';\n            c.fillRect(drawX + Math.random() * this.w, drawY + 1, 2, 2);\n          }\n        }\n      }\n    }\n\n    class Collectible {\n      constructor(x, y, type) {\n        this.x = x;\n        this.y = y;\n        this.type = type; // 'STAR', 'WISP', 'SODA'\n        this.w = 16;\n        this.h = 16;\n        this.frame = Math.random() * 10;\n        this.collected = false;\n      }\n\n      update() {\n        this.x -= gameSpeed;\n        this.frame += 0.1;\n      }\n\n      draw(c) {\n        const drawX = Math.round(this.x);\n        const floatY = Math.round(this.y + Math.sin(this.frame) * 3);\n\n        if (this.type === 'STAR') {\n          // 4-Point Retro Star\n          c.fillStyle = PALETTE.starYellow;\n          c.fillRect(drawX + 6, floatY + 2, 4, 12);\n          c.fillRect(drawX + 2, floatY + 6, 12, 4);\n          c.fillStyle = '#ffffff';\n          c.fillRect(drawX + 6, floatY + 6, 4, 4);\n\n        } else if (this.type === 'WISP') {\n          // Spectral cyan wisp\n          c.fillStyle = 'rgba(72, 219, 251, 0.8)';\n          c.beginPath();\n          c.arc(drawX + 8, floatY + 8, 6, 0, Math.PI * 2);\n          c.fill();\n          c.fillStyle = '#ffffff';\n          c.beginPath();\n          c.arc(drawX + 8, floatY + 8, 3, 0, Math.PI * 2);\n          c.fill();\n\n        } else if (this.type === 'SODA') {\n          // Ghost Turbo Soda\n          c.fillStyle = '#a29bfe';\n          c.fillRect(drawX + 4, floatY + 2, 8, 12);\n          c.fillStyle = '#ff7675';\n          c.fillRect(drawX + 4, floatY + 5, 8, 5);\n          c.fillStyle = '#ffffff';\n          c.fillRect(drawX + 6, floatY, 4, 2);\n        }\n      }\n    }\n\n    // Particle FX\n    function createDust(x, y, count = 4) {\n      for (let i = 0; i < count; i++) {\n        particles.push({\n          x: x + (Math.random() - 0.5) * 8,\n          y: y - Math.random() * 3,\n          vx: -gameSpeed * 0.4 - Math.random() * 1.5,\n          vy: -Math.random() * 1.2,\n          size: Math.random() * 3 + 1,\n          color: PALETTE.sidewalkTop,\n          life: 18\n        });\n      }\n    }\n\n    function createSparks(x, y, count = 5, color = PALETTE.spark) {\n      for (let i = 0; i < count; i++) {\n        particles.push({\n          x,\n          y,\n          vx: (Math.random() - 0.7) * 3 - gameSpeed * 0.3,\n          vy: (Math.random() - 0.5) * 3,\n          size: Math.random() * 2 + 1,\n          color: color,\n          life: 16\n        });\n      }\n    }\n\n    function addFloatingText(x, y, text, color = '#feca57') {\n      floatTexts.push({\n        x,\n        y,\n        text,\n        color,\n        vy: -0.9,\n        life: 35\n      });\n    }\n\n    // --- PARALLAX BACKGROUND DRAWING ---\n    function drawBackground(c) {\n      // 1. Twilight Sky Gradient\n      const skyGrad = c.createLinearGradient(0, 0, 0, VIRTUAL_HEIGHT * 0.65);\n      skyGrad.addColorStop(0, PALETTE.skyTop);\n      skyGrad.addColorStop(0.5, PALETTE.skyMid);\n      skyGrad.addColorStop(1, PALETTE.skyBottom);\n      c.fillStyle = skyGrad;\n      c.fillRect(0, 0, VIRTUAL_WIDTH, VIRTUAL_HEIGHT * 0.7);\n\n      // 2. Glowing Moon\n      const moonX = VIRTUAL_WIDTH - 90;\n      const moonY = 45;\n      c.fillStyle = PALETTE.moonGlow;\n      c.beginPath();\n      c.arc(moonX, moonY, 26, 0, Math.PI * 2);\n      c.fill();\n\n      c.fillStyle = 'rgba(247, 241, 203, 0.4)';\n      c.beginPath();\n      c.arc(moonX, moonY, 18, 0, Math.PI * 2);\n      c.fill();\n\n      c.fillStyle = PALETTE.moon;\n      c.beginPath();\n      c.arc(moonX, moonY, 11, 0, Math.PI * 2);\n      c.fill();\n\n      // Soft stars\n      c.fillStyle = 'rgba(255, 255, 255, 0.75)';\n      const starPositions = [\n        [40, 25], [110, 45], [180, 20], [240, 38], [320, 15], [390, 50], [450, 30]\n      ];\n      starPositions.forEach(([sx, sy], i) => {\n        if ((Math.floor(distance * 0.05) + i) % 3 !== 0) {\n          c.fillRect(sx, sy, 2, 2);\n        }\n      });\n\n      // 3. Clouds (slow parallax)\n      bgOffsetClouds = (bgOffsetClouds + gameSpeed * 0.08) % VIRTUAL_WIDTH;\n      c.fillStyle = PALETTE.clouds;\n      drawCloudCluster(c, 70 - bgOffsetClouds, 30);\n      drawCloudCluster(c, 70 - bgOffsetClouds + VIRTUAL_WIDTH, 30);\n      drawCloudCluster(c, 290 - bgOffsetClouds, 22);\n      drawCloudCluster(c, 290 - bgOffsetClouds + VIRTUAL_WIDTH, 22);\n\n      // 4. Distant Mountain Silhouettes\n      bgOffsetMountains = (bgOffsetMountains + gameSpeed * 0.15) % VIRTUAL_WIDTH;\n      c.fillStyle = PALETTE.mountains;\n      drawMountainLayer(c, -bgOffsetMountains);\n      drawMountainLayer(c, -bgOffsetMountains + VIRTUAL_WIDTH);\n\n      // 5. Far Skyline (Silhouettes with warm windows)\n      bgOffsetSkylineFar = (bgOffsetSkylineFar + gameSpeed * 0.3) % 240;\n      drawSkyline(c, -bgOffsetSkylineFar, 110, PALETTE.skylineFar, 0.3);\n      drawSkyline(c, -bgOffsetSkylineFar + 240, 110, PALETTE.skylineFar, 0.3);\n      drawSkyline(c, -bgOffsetSkylineFar + 480, 110, PALETTE.skylineFar, 0.3);\n\n      // 6. Near Skyline\n      bgOffsetSkylineNear = (bgOffsetSkylineNear + gameSpeed * 0.5) % 300;\n      drawSkyline(c, -bgOffsetSkylineNear, 125, PALETTE.skylineNear, 0.7);\n      drawSkyline(c, -bgOffsetSkylineNear + 300, 125, PALETTE.skylineNear, 0.7);\n      drawSkyline(c, -bgOffsetSkylineNear + 600, 125, PALETTE.skylineNear, 0.7);\n\n      // 7. Waterfront / River Bay\n      c.fillStyle = PALETTE.water;\n      c.fillRect(0, 168, VIRTUAL_WIDTH, 22);\n\n      // Water ripples\n      bgOffsetWater = (bgOffsetWater + gameSpeed * 0.7) % 60;\n      c.fillStyle = PALETTE.waterHighlight;\n      for (let rx = -bgOffsetWater; rx < VIRTUAL_WIDTH; rx += 36) {\n        c.fillRect(rx, 174, 16, 1);\n        c.fillRect(rx + 18, 180, 12, 1);\n        c.fillRect(rx + 8, 185, 20, 1);\n      }\n\n      // 8. Promenade Railing & Bushes\n      bgOffsetRailing = (bgOffsetRailing + gameSpeed * 0.9) % 32;\n      drawRailingAndBushes(c, -bgOffsetRailing);\n\n      // 9. Sidewalk / Promenade Ground\n      drawSidewalk(c);\n    }\n\n    function drawCloudCluster(c, cx, cy) {\n      c.beginPath();\n      c.arc(cx + 14, cy + 12, 9, 0, Math.PI * 2);\n      c.arc(cx + 28, cy + 9, 12, 0, Math.PI * 2);\n      c.arc(cx + 44, cy + 13, 10, 0, Math.PI * 2);\n      c.arc(cx + 56, cy + 15, 7, 0, Math.PI * 2);\n      c.fill();\n    }\n\n    function drawMountainLayer(c, ox) {\n      c.beginPath();\n      c.moveTo(ox, 170);\n      c.lineTo(ox + 60, 138);\n      c.lineTo(ox + 130, 160);\n      c.lineTo(ox + 210, 130);\n      c.lineTo(ox + 310, 165);\n      c.lineTo(ox + 400, 134);\n      c.lineTo(ox + 480, 170);\n      c.lineTo(ox + 480, 190);\n      c.lineTo(ox, 190);\n      c.closePath();\n      c.fill();\n    }\n\n    function drawSkyline(c, ox, baseH, color, windowDensity) {\n      c.fillStyle = color;\n      const buildings = [\n        { w: 26, h: 48 }, { w: 34, h: 62 }, { w: 20, h: 38 },\n        { w: 42, h: 74 }, { w: 28, h: 54 }, { w: 32, h: 44 },\n        { w: 24, h: 68 }, { w: 38, h: 50 }, { w: 30, h: 58 }\n      ];\n\n      let curX = ox;\n      buildings.forEach((b, idx) => {\n        const by = 175 - b.h;\n        c.fillStyle = color;\n        c.fillRect(curX, by, b.w, b.h);\n\n        // Antenna\n        if (idx % 2 === 0) {\n          c.fillRect(curX + Math.floor(b.w / 2), by - 10, 2, 10);\n          c.fillStyle = '#ff6b81';\n          c.fillRect(curX + Math.floor(b.w / 2), by - 12, 2, 2);\n          c.fillStyle = color;\n        }\n\n        // Lit Windows\n        if (windowDensity > 0.4) {\n          for (let wy = by + 6; wy < 170; wy += 8) {\n            for (let wx = curX + 4; wx < curX + b.w - 4; wx += 6) {\n              if ((wx * 13 + wy * 7) % 5 === 0) {\n                c.fillStyle = ((wx + wy) % 2 === 0) ? PALETTE.windowYellow : PALETTE.windowCyan;\n                c.fillRect(wx, wy, 2, 3);\n              }\n            }\n          }\n        }\n\n        curX += b.w + 4;\n      });\n    }\n\n    function drawRailingAndBushes(c, ox) {\n      // Lush purple-green bushes along the railing\n      for (let bx = ox; bx < VIRTUAL_WIDTH + 40; bx += 32) {\n        c.fillStyle = PALETTE.bushGreen;\n        c.beginPath();\n        c.arc(bx + 16, 186, 12, Math.PI, 0, false);\n        c.fill();\n\n        c.fillStyle = PALETTE.bushHighlight;\n        c.fillRect(bx + 12, 178, 6, 2);\n      }\n\n      // Promenade Railing\n      c.fillStyle = PALETTE.railing;\n      // Top horizontal rail\n      c.fillRect(0, 178, VIRTUAL_WIDTH, 3);\n      // Mid horizontal rail\n      c.fillRect(0, 185, VIRTUAL_WIDTH, 2);\n\n      // Posts & Balusters\n      for (let px = ox; px < VIRTUAL_WIDTH + 32; px += 32) {\n        c.fillStyle = PALETTE.railingPost;\n        c.fillRect(px, 174, 5, 18);\n        c.fillRect(px - 1, 173, 7, 2); // Post cap\n      }\n    }\n\n    function drawSidewalk(c) {\n      // Curb / Top border of sidewalk\n      c.fillStyle = PALETTE.sidewalkTop;\n      c.fillRect(0, 192, VIRTUAL_WIDTH, 4);\n\n      // Sidewalk Main Face\n      c.fillStyle = PALETTE.sidewalkFace;\n      c.fillRect(0, 196, VIRTUAL_WIDTH, VIRTUAL_HEIGHT - 196);\n\n      // Pavement tile cracks and seams scrolling with ground speed\n      bgOffsetGround = (bgOffsetGround + gameSpeed) % 48;\n      c.fillStyle = PALETTE.sidewalkLine;\n      for (let gx = -bgOffsetGround; gx < VIRTUAL_WIDTH + 48; gx += 48) {\n        c.fillRect(gx, 196, 2, VIRTUAL_HEIGHT - 196);\n        // Horizontal slab lines\n        c.fillRect(gx - 24, 218, 48, 1);\n        c.fillRect(gx, 245, 48, 1);\n      }\n\n      // Curb highlight\n      c.fillStyle = 'rgba(255, 255, 255, 0.12)';\n      c.fillRect(0, 192, VIRTUAL_WIDTH, 1);\n    }\n\n    // --- GAME LOOP & UPDATES ---\n    let spawnTimer = 0;\n    let nextSpawnDistance = 60;\n\n    function resetGame() {\n      score = 0;\n      distance = 0;\n      starsCollected = 0;\n      tricksCount = 0;\n      lives = 3;\n      gameSpeed = baseSpeed;\n      combo = 1;\n      comboTimer = 0;\n\n      obstacles = [];\n      collectibles = [];\n      particles = [];\n      floatTexts = [];\n      spawnTimer = 0;\n\n      player.reset();\n      updateHUD();\n      sound.startBGM();\n    }\n\n    function refreshRecordUI() {\n      const rec = document.getElementById('rec-display');\n      if (rec) rec.textContent = recordBroken ? Math.floor(score) : recordToBeat;\n      const startRec = document.getElementById('start-record');\n      if (startRec) startRec.textContent = recordToBeat > 0 ? '🏆 RÉCORD A SUPERAR: ' + recordToBeat : '🏆 AÚN SIN RÉCORD: ¡ESTABLÉCELO!';\n      const chip = document.getElementById('rec-chip');\n      if (chip) chip.style.borderColor = recordBroken ? '#feca57' : '';\n    }\n\n    function updateHUD() {\n      if (Math.floor(score) < 1) { recordBroken = false; recordToBeat = highScore; }\n      if (!recordBroken && recordToBeat > 0 && Math.floor(score) > recordToBeat) {\n        recordBroken = true;\n        const banner = document.getElementById('record-banner');\n        if (banner) { banner.style.opacity = '1'; setTimeout(() => { banner.style.opacity = '0'; }, 2600); }\n        vitraSend({ type: 'record', score: Math.floor(score) });\n      }\n      refreshRecordUI();\n      scoreDisplay.textContent = String(Math.floor(score)).padStart(5, '0');\n      distanceDisplay.textContent = Math.floor(distance) + 'm';\n      starsDisplay.textContent = starsCollected;\n\n      // Speed indicator\n      const currentKmh = Math.floor(gameSpeed * 6.5);\n      speedText.textContent = currentKmh + ' km/h';\n      const pct = Math.min(100, Math.max(10, ((gameSpeed - baseSpeed) / (maxSpeed - baseSpeed)) * 90 + 15));\n      speedMeter.style.width = pct + '%';\n\n      // Update hearts\n      heartsContainer.innerHTML = '';\n      for (let i = 0; i < 3; i++) {\n        const heart = document.createElement('span');\n        heart.className = 'text-base transition-opacity';\n        if (i < lives) {\n          heart.textContent = '👻';\n          heart.style.opacity = '1';\n        } else {\n          heart.textContent = '💀';\n          heart.style.opacity = '0.35';\n        }\n        heartsContainer.appendChild(heart);\n      }\n    }\n\n    function addScore(pts) {\n      score += pts;\n      scoreDisplay.textContent = String(Math.floor(score)).padStart(5, '0');\n    }\n\n    function showTrickBanner(name, pts) {\n      trickNameEl.textContent = name;\n      trickPointsEl.textContent = '+' + pts + ' PTS';\n      trickBanner.style.opacity = '1';\n      trickBanner.style.transform = 'translate(-50%, 0)';\n\n      if (trickTimeout) clearTimeout(trickTimeout);\n      trickTimeout = setTimeout(() => {\n        trickBanner.style.opacity = '0';\n        trickBanner.style.transform = 'translate(-50%, -8px)';\n      }, 900);\n    }\n\n    function updateCombo() {\n      if (comboTimer > 0) {\n        comboTimer--;\n        comboBadge.style.opacity = '1';\n        comboBadge.textContent = 'x' + combo + ' COMBO!';\n      } else {\n        combo = 1;\n        comboBadge.style.opacity = '0';\n      }\n    }\n\n    function spawnEntities() {\n      spawnTimer++;\n      if (spawnTimer >= nextSpawnDistance) {\n        spawnTimer = 0;\n        // Adjust spacing based on speed\n        nextSpawnDistance = Math.floor(65 + Math.random() * 55 - (gameSpeed - baseSpeed) * 4);\n\n        const rand = Math.random();\n        if (rand < 0.45) {\n          // Stone Block Obstacle (Signature element from reference!)\n          obstacles.push(new Obstacle(VIRTUAL_WIDTH + 20, 'STONE'));\n          // Chance of star right above stone\n          if (Math.random() < 0.6) {\n            collectibles.push(new Collectible(VIRTUAL_WIDTH + 26, GROUND_Y - 58, 'STAR'));\n          }\n        } else if (rand < 0.70) {\n          // Park Bench (Grindable!)\n          obstacles.push(new Obstacle(VIRTUAL_WIDTH + 20, 'BENCH'));\n          // Stars along bench\n          collectibles.push(new Collectible(VIRTUAL_WIDTH + 35, GROUND_Y - 45, 'STAR'));\n        } else if (rand < 0.85) {\n          // Fire Hydrant\n          obstacles.push(new Obstacle(VIRTUAL_WIDTH + 20, 'HYDRANT'));\n        } else {\n          // Flying Twilight Bat (Duck or jump very early)\n          obstacles.push(new Obstacle(VIRTUAL_WIDTH + 20, 'BAT'));\n          // Star near ground to encourage sliding\n          collectibles.push(new Collectible(VIRTUAL_WIDTH + 20, GROUND_Y - 14, 'STAR'));\n        }\n\n        // Random bonus star/wisp trails\n        if (Math.random() < 0.35) {\n          const type = Math.random() < 0.2 ? 'SODA' : 'WISP';\n          collectibles.push(new Collectible(VIRTUAL_WIDTH + 90, GROUND_Y - 60 - Math.random() * 25, type));\n        }\n      }\n    }\n\n    function checkCollisions() {\n      // Ronnie hitbox\n      const px = player.x + 4;\n      const pw = player.w - 8;\n      let py = player.y + 4;\n      let ph = player.h - 8;\n\n      if (player.isSliding) {\n        py = player.y + 14;\n        ph = 14;\n      }\n\n      // Check Obstacles\n      player.isGrinding = false;\n      for (let i = obstacles.length - 1; i >= 0; i--) {\n        const obs = obstacles[i];\n        const ox = obs.x;\n        const oy = obs.y;\n        const ow = obs.w;\n        const oh = obs.h;\n\n        // Grind check on Benches\n        if (obs.type === 'BENCH' && obs.canGrind) {\n          if (px + pw > ox && px < ox + ow) {\n            // If Ronnie lands on top of bench\n            if (player.vy >= 0 && Math.abs(player.y + player.h - oy) <= 8) {\n              player.isGrinding = true;\n              player.y = oy - player.h + 2;\n              combo = Math.min(5, combo + 1);\n              comboTimer = 70;\n              continue;\n            }\n          }\n        }\n\n        // Regular AABB collision\n        if (px + pw > ox && px < ox + ow && py + ph > oy && py < oy + oh) {\n          if (player.invulnerableTimer <= 0) {\n            // Collision hit!\n            lives--;\n            sound.hit();\n            player.invulnerableTimer = 60; // 1 second invulnerability\n            createSparks(player.x + 16, player.y + 16, 12, '#ff4757');\n            addFloatingText(player.x, player.y - 10, '-1 VIDA!', '#ff6b81');\n            combo = 1;\n            comboTimer = 0;\n            updateHUD();\n\n            if (lives <= 0) {\n              triggerGameOver();\n              return;\n            }\n          }\n        }\n\n        // Clear passed obstacles\n        if (obs.x + obs.w < -20) {\n          obstacles.splice(i, 1);\n        }\n      }\n\n      // Check Collectibles\n      for (let i = collectibles.length - 1; i >= 0; i--) {\n        const item = collectibles[i];\n        if (px + pw > item.x && px < item.x + item.w && py + ph > item.y && py < item.y + item.h) {\n          // Collected!\n          if (item.type === 'STAR') {\n            starsCollected++;\n            const pts = 100 * combo;\n            addScore(pts);\n            sound.star();\n            createSparks(item.x + 8, item.y + 8, 8, PALETTE.starYellow);\n            addFloatingText(item.x, item.y, '+' + pts, PALETTE.starYellow);\n            combo = Math.min(5, combo + 1);\n            comboTimer = 90;\n          } else if (item.type === 'WISP') {\n            const pts = 50 * combo;\n            addScore(pts);\n            sound.playTone(660, 0.15, 'sine', 0.1);\n            createSparks(item.x + 8, item.y + 8, 6, '#48dbfb');\n            addFloatingText(item.x, item.y, '+' + pts, '#48dbfb');\n          } else if (item.type === 'SODA') {\n            addScore(250);\n            player.invulnerableTimer = 140; // Super shield\n            sound.playTone(523, 0.1, 'sine', 0.15);\n            setTimeout(() => sound.playTone(784, 0.2, 'sine', 0.18), 80);\n            createSparks(item.x + 8, item.y + 8, 14, '#ff9ff3');\n            addFloatingText(item.x, item.y, '¡TURBO!', '#ff9ff3');\n          }\n\n          collectibles.splice(i, 1);\n          updateHUD();\n        } else if (item.x + item.w < -20) {\n          collectibles.splice(i, 1);\n        }\n      }\n    }\n\n    function triggerGameOver() {\n      gameState = 'GAMEOVER';\n      sound.stopBGM();\n      sound.gameOver();\n\n      const wasNewRecord = Math.floor(score) > highScore;\n      if (score > highScore) {\n        highScore = Math.floor(score);\n        try {\n          localStorage.setItem('ronnie_high_score', highScore);\n        } catch(e) {}\n      }\n\n      finalScoreEl.textContent = Math.floor(score);\n      highScoreEl.textContent = highScore;\n      const badge = document.getElementById('new-record-badge');\n      if (badge) badge.classList.toggle('hidden', !wasNewRecord);\n      vitraSend({ type: 'gameover', score: Math.floor(score), best: highScore, newRecord: wasNewRecord });\n      recordToBeat = highScore; recordBroken = false; refreshRecordUI();\n      finalDistEl.textContent = Math.floor(distance) + 'm';\n      finalStarsEl.textContent = starsCollected;\n      finalTricksEl.textContent = tricksCount;\n\n      gameOverScreen.classList.remove('hidden');\n    }\n\n    // Main Update Loop\n    function updateGame() {\n      if (gameState !== 'PLAYING') return;\n\n      // Distance and speed progression\n      distance += gameSpeed * 0.08;\n      addScore(gameSpeed * 0.15);\n\n      if (gameSpeed < maxSpeed) {\n        gameSpeed += 0.0006;\n      }\n\n      player.update();\n      updateCombo();\n      spawnEntities();\n\n      obstacles.forEach(obs => obs.update());\n      collectibles.forEach(col => col.update());\n\n      // Update Particles\n      for (let i = particles.length - 1; i >= 0; i--) {\n        const p = particles[i];\n        p.x += p.vx;\n        p.y += p.vy;\n        p.life--;\n        if (p.life <= 0) particles.splice(i, 1);\n      }\n\n      // Update Float Texts\n      for (let i = floatTexts.length - 1; i >= 0; i--) {\n        const ft = floatTexts[i];\n        ft.y += ft.vy;\n        ft.life--;\n        if (ft.life <= 0) floatTexts.splice(i, 1);\n      }\n\n      checkCollisions();\n      updateHUD();\n    }\n\n    // Main Render Loop\n    function renderGame() {\n      ctx.clearRect(0, 0, VIRTUAL_WIDTH, VIRTUAL_HEIGHT);\n\n      // Draw Parallax World\n      drawBackground(ctx);\n\n      // Draw Entities\n      obstacles.forEach(obs => obs.draw(ctx));\n      collectibles.forEach(col => col.draw(ctx));\n\n      // Draw Player\n      player.draw(ctx);\n\n      // Draw Particles\n      particles.forEach(p => {\n        ctx.fillStyle = p.color;\n        ctx.fillRect(Math.round(p.x), Math.round(p.y), Math.round(p.size), Math.round(p.size));\n      });\n\n      // Draw Floating Popups\n      floatTexts.forEach(ft => {\n        ctx.save();\n        ctx.fillStyle = ft.color;\n        ctx.font = '8px \"Press Start 2P\", monospace';\n        ctx.shadowColor = '#000';\n        ctx.shadowBlur = 3;\n        ctx.fillText(ft.text, Math.round(ft.x), Math.round(ft.y));\n        ctx.restore();\n      });\n    }\n\n    // Continuous Animation Frame\n    function gameLoop() {\n      updateGame();\n      renderGame();\n      requestAnimationFrame(gameLoop);\n    }\n\n    // --- CANVAS RESIZE & SCALING ---\n    function resizeCanvas() {\n      const rect = container.getBoundingClientRect();\n      canvas.width = VIRTUAL_WIDTH;\n      canvas.height = VIRTUAL_HEIGHT;\n      ctx.imageSmoothingEnabled = false;\n      renderGame();\n    }\n\n    // --- CONTROLS & EVENT LISTENERS ---\n    function setupControls() {\n      // Keyboard input\n      window.addEventListener('keydown', (e) => {\n        // Prevent default scrolling on arrow keys and space\n        if (['Space', 'ArrowUp', 'ArrowDown', 'KeyW', 'KeyS'].includes(e.code)) {\n          e.preventDefault();\n        }\n\n        sound.init();\n\n        if (gameState === 'START') {\n          if (e.code === 'Space' || e.code === 'Enter') {\n            startGame();\n          }\n          return;\n        }\n\n        if (gameState === 'GAMEOVER') {\n          if (e.code === 'Space' || e.code === 'Enter') {\n            restartGame();\n          }\n          return;\n        }\n\n        if (gameState === 'PLAYING') {\n          if (e.code === 'Space' || e.code === 'ArrowUp' || e.code === 'KeyW') {\n            player.jump();\n          } else if (e.code === 'ArrowDown' || e.code === 'KeyS') {\n            player.slide();\n          } else if (e.code === 'KeyX' || e.code === 'KeyK') {\n            player.doTrick();\n          } else if (e.code === 'KeyP' || e.code === 'Escape') {\n            togglePause();\n          }\n        }\n      });\n\n      // On-screen buttons\n      const btnPlay = document.getElementById('btn-play');\n      const btnRestart = document.getElementById('btn-restart');\n      const btnResume = document.getElementById('btn-resume');\n      const btnPause = document.getElementById('btn-pause');\n      const btnSound = document.getElementById('btn-sound');\n      const btnCrt = document.getElementById('btn-crt');\n\n      const touchJump = document.getElementById('touch-jump');\n      const touchTrick = document.getElementById('touch-trick');\n      const touchSlide = document.getElementById('touch-slide');\n\n      btnPlay.addEventListener('click', startGame);\n      btnRestart.addEventListener('click', restartGame);\n      btnResume.addEventListener('click', togglePause);\n      btnPause.addEventListener('click', togglePause);\n\n      btnSound.addEventListener('click', () => {\n        sound.init();\n        const isMuted = sound.toggleMute();\n        soundIcon.textContent = isMuted ? '🔇' : '🔊';\n      });\n\n      btnCrt.addEventListener('click', () => {\n        container.classList.toggle('crt-overlay');\n        btnCrt.classList.toggle('bg-[#6c5ce7]');\n      });\n\n      // Touch / Click actions for gameplay\n      touchJump.addEventListener('pointerdown', (e) => {\n        e.preventDefault();\n        sound.init();\n        if (gameState === 'PLAYING') player.jump();\n      });\n\n      touchTrick.addEventListener('pointerdown', (e) => {\n        e.preventDefault();\n        sound.init();\n        if (gameState === 'PLAYING') player.doTrick();\n      });\n\n      touchSlide.addEventListener('pointerdown', (e) => {\n        e.preventDefault();\n        sound.init();\n        if (gameState === 'PLAYING') player.slide();\n      });\n\n      // Canvas click jumps as well\n      canvas.addEventListener('pointerdown', (e) => {\n        sound.init();\n        if (gameState === 'PLAYING') {\n          player.jump();\n        }\n      });\n\n      window.addEventListener('resize', resizeCanvas);\n    }\n\n    function startGame() {\n      sound.init();\n      startScreen.classList.add('hidden');\n      gameState = 'PLAYING';\n      resetGame();\n    }\n\n    function restartGame() {\n      gameOverScreen.classList.add('hidden');\n      gameState = 'PLAYING';\n      resetGame();\n    }\n\n    function togglePause() {\n      if (gameState === 'PLAYING') {\n        gameState = 'PAUSED';\n        pauseScreen.classList.remove('hidden');\n        sound.stopBGM();\n      } else if (gameState === 'PAUSED') {\n        gameState = 'PLAYING';\n        pauseScreen.classList.add('hidden');\n        sound.startBGM();\n      }\n    }\n\n    // --- INITIALIZATION ---\n    window.onload = () => {\n      resizeCanvas();\n      setupControls();\n      container.classList.add('crt-overlay'); // Default retro scanline enabled\n      renderGame();\n      requestAnimationFrame(gameLoop);\n    };\n  </script>\n<script>try { if (typeof refreshRecordUI === \"function\") refreshRecordUI(); } catch (e) {}</script>\n\n<script>\n  (function () {\n    function send(msg) { if (window.ReactNativeWebView) window.ReactNativeWebView.postMessage(JSON.stringify(msg)); }\n    window.__vitraPause = function () { var b = document.getElementById('btn-pause'); var p = document.getElementById('pause-screen'); if (b && p && p.classList.contains('hidden')) b.click(); };\n    var best = 0;\n    setInterval(function () {\n      var el = document.getElementById('score-display');\n      var score = el ? parseInt(el.textContent, 10) || 0 : 0;\n      if (score > best) { best = score; send({ type: 'score', score: score }); }\n    }, 2000);\n    send({ type: 'ready' });\n  })();\n</script>\n</body>\n</html>";
